SELECT COUNT(*) AS rentable_listings
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT COUNT(*) AS deactivated_accounts
FROM nlq.students
WHERE account_status = 'deactivated';

SELECT COUNT(*) AS reviews_with_comment
FROM nlq.reviews
WHERE comment IS NOT NULL;

select count(*) as conversations_no_reply
from nlq.conversations
where first_seller_reply_at is null;

SELECT COUNT(*) AS listings_taken_down_by_sellers
FROM nlq.listings_all
WHERE status = 'removed';

SELECT round(avg(extract(epoch FROM (resolved_at - filed_at))/86400)::numeric, 2) AS avg_days_to_resolve
FROM nlq.reports
WHERE status = 'resolved';

SELECT COUNT(*) AS listings_no_photos
FROM nlq.listings_all
WHERE photo_count = 0;
